 function renderNotes(){const list=panel.querySelector('.review-sidebar-body');if(panel.hidden)return;const items=current().turns.flatMap((t,i)=>(t.reviewDraft?.comments||[]).map(c=>({...c,turn:t.id,number:i+1})));list.innerHTML=items.length?items.map(c=>'<section class="review-note" data-id="'+esc(c.id)+'" data-turn="'+esc(c.turn)+'"><div class="review-note-meta">第 '+c.number+' 轮 · '+(c.orphan?'原位置已删除':c.resolved?'已解决':'评论')+'</div><blockquote>'+esc(c.quote)+'</blockquote><p>'+esc(c.text)+' <button class="review-edit-action" data-note-action="edit-note" aria-label="编辑评论">编辑</button></p>'+(c.replies||[]).map((r,i)=>'<p class="review-reply">'+esc(r)+' <button class="review-edit-action" data-note-action="edit-reply" data-reply-index="'+i+'" aria-label="编辑回复">编辑</button></p>').join('')+'<div class="review-note-actions"><button data-note-action="locate" '+(c.orphan?'disabled':'')+'>定位</button><button data-note-action="reply">回复</button><button data-note-action="resolve">'+(c.resolved?'重新打开':'解决')+'</button><button data-note-action="delete">删除</button></div><div class="review-reply-box" hidden><textarea aria-label="回复评论" placeholder="写下回复"></textarea><button data-note-action="send-reply">保存回复</button></div><div class="review-edit-box" hidden><textarea aria-label="编辑评论或回复"></textarea><button data-note-action="save-edit">保存修改</button><button data-note-action="cancel-edit">取消</button></div></section>').join(''):'<p class="review-empty">选择回答中的文字，点击「评论选区」。评论保存在当前会话，默认不会发给 AI；可在发送时选择携带。</p>';}
 const sendToggle=document.createElement('select');sendToggle.id='review-send';sendToggle.className='review-send';sendToggle.setAttribute('aria-label','当前末轮的批注携带方式');sendToggle.title='设置当前末轮：不选、长期或临时携带';sendToggle.innerHTML='<option value="none">末轮：不选</option><option value="long">末轮：长期</option><option value="temporary">末轮：临时</option>';$('entries-button').after(sendToggle);
 const selectEarlier=document.createElement('button');selectEarlier.id='review-select-earlier';selectEarlier.className='review-send';selectEarlier.type='button';selectEarlier.title='选择跨会话携带的轮次批注';sendToggle.after(selectEarlier);
 const pinnedSummary=document.createElement('div');pinnedSummary.className='review-pinned-summary';pinnedSummary.setAttribute('aria-label','持续携带的批注来源');document.querySelector('.composer-toolbar').before(pinnedSummary);
 function pinList(){return state.reviewPinnedTurns||[];}
