 function updateSendToggle(){const last=current().turns.at(-1);sendToggle.disabled=!last;sendToggle.value=last?mode(current().id,last.id):'none';const pins=selections(),missing=pins.filter(pin=>!source(pin).turn).length;selectEarlier.textContent='携带轮次'+(pins.length?' · '+pins.length:'')+(missing?' · '+missing+' 项不可用':'');pinnedSummary.hidden=!pins.length;pinnedSummary.innerHTML=pins.map(pin=>{const s=source(pin),label=(pin.mode==='long'?'长期':'临时')+' · '+(s.turn?(s.conversation.title+' · 第 '+s.index+' 轮 · '+(s.turn.reviewDraft?.comments?.length||0)+' 条'):'来源不可用 · '+pin.conversationId+' / '+pin.turnId);return '<button type="button" class="review-pinned-chip'+(s.turn?'':' unavailable')+'" data-unpin-conversation="'+esc(pin.conversationId)+'" data-unpin-turn="'+esc(pin.turnId)+'" title="点击取消携带">'+esc(label)+' ×</button>';}).join('');}
