 function pickOptions(value){return ['none','long','temporary'].map(x=>'<option value="'+x+'"'+(value===x?' selected':'')+'>'+({none:'不选',long:'长期',temporary:'临时'})[x]+'</option>').join('');}
 function renderPicker(){const selected=selections(),items=state.conversations.flatMap(conversation=>conversation.turns.map((turn,index)=>({conversation,turn,index:index+1})));const valid=items.map(({conversation,turn,index})=>{const comments=turn.reviewDraft?.comments||[];return '<label class="review-pick-item"><select aria-label="'+esc(conversation.title)+'第 '+index+' 轮携带方式" data-pick-conversation="'+esc(conversation.id)+'" data-pick-turn="'+esc(turn.id)+'">'+pickOptions(mode(conversation.id,turn.id))+'</select><span><small>'+esc(conversation.title)+' · 第 '+index+' 轮 · '+comments.length+' 条批注</small><span>'+esc((turn.prompt??turn.question??'').slice(0,100))+'</span></span></label>';});const missing=selected.filter(pin=>!source(pin).turn).map(pin=>'<label class="review-pick-item unavailable"><select aria-label="不可用来源携带方式" data-pick-conversation="'+esc(pin.conversationId)+'" data-pick-turn="'+esc(pin.turnId)+'">'+pickOptions(pin.mode)+'</select><span>来源不可用：'+esc(pin.conversationId)+' / '+esc(pin.turnId)+'（取消后才可发送）</span></label>');picker.querySelector('.review-pick-list').innerHTML=missing.concat(valid).join('')||'<p class="review-empty">尚无可选轮次。</p>';}
